enum FEMENUCMD
{
    FEMENUCMD_SELECT,
    FEMENUCMD_START,
    FEMENUCMD_UP,
    FEMENUCMD_DOWN,
    FEMENUCMD_LEFT,
    FEMENUCMD_RIGHT,
    FEMENUCMD_CROSS,
    FEMENUCMD_TRIANGLE,
    FEMENUCMD_SQUARE,
    FEMENUCMD_CIRCLE,
    FEMENUCMD_L1,
    FEMENUCMD_R1,
    FEMENUCMD_L2,
    FEMENUCMD_R2,
    FEMENUCMD_END
};

class FEMenuSystem;
class FEManager;
class Font;

class FEMenu
{
public:
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(void *, bool = true);
    virtual void setVis(void *);
    virtual void Add(void *);
    virtual void Init();
    virtual void Load(bool);
    virtual void Load();
    virtual void Draw();
    virtual void DrawTop();
    virtual void UpdateInScene();
    virtual void Update(float);
    virtual void HighlightDefault();
    virtual void OnActivate();
    virtual void OnActivate(int);
    virtual void OnUnactivate(FEMenu *);
    virtual void OnSelect(int);
    virtual void OnStart(int);
    virtual void OnUp(int);
    virtual void OnDown(int);
    virtual void OnLeft(int);
    virtual void OnRight(int);
    virtual void OnCross(int);
    virtual void OnTriangle(int);
    virtual void OnSquare(int);
    virtual void OnCircle(int);
    virtual void OnL1(int);
    virtual void OnR1(int);
    virtual void OnL2(int);
    virtual void OnR2(int);
    virtual void OnAnyButtonPress(int, int);
    virtual void OnButtonRelease(int, int);
};

class FEMenuSystem
{
protected:
    bool button_down[FEMENUCMD_END][2];
    int device_flags;
public:
    FEMenu **menus;
    FEManager *manager;
    int active;
    int size;
    int count;
    Font *font;
    virtual ~FEMenuSystem();
    virtual void InitAll();
    virtual void Add(FEMenu *);
    virtual void MakeActive(int, int = 1);
    virtual void Update(float);
    virtual void UpdateButtonDown();
    virtual void Draw();
    virtual void Select(int, int) = 0;
    virtual void Exit();
    virtual void startDraw(int = -1, const bool = true);
    virtual void endDraw(const bool = true);
    virtual FEMenu *GetActiveMenu();
protected:
    virtual void cons(int, FEManager *, Font *);
    virtual void OnButtonPress(int, int);
};

void FEMenuSystem::OnButtonPress(int button, int controller)
{
    menus[active]->OnAnyButtonPress(controller, button);
    switch(button)
    {
    case FEMENUCMD_SELECT  : menus[active]->OnSelect(controller); break;
    case FEMENUCMD_START   : menus[active]->OnStart(controller); break;
    case FEMENUCMD_UP      : menus[active]->OnUp(controller); break;
    case FEMENUCMD_DOWN    : menus[active]->OnDown(controller); break;
    case FEMENUCMD_LEFT    : menus[active]->OnLeft(controller); break;
    case FEMENUCMD_RIGHT   : menus[active]->OnRight(controller); break;
    case FEMENUCMD_CROSS   : menus[active]->OnCross(controller); break;
    case FEMENUCMD_TRIANGLE: menus[active]->OnTriangle(controller); break;
    case FEMENUCMD_SQUARE  : menus[active]->OnSquare(controller); break;
    case FEMENUCMD_CIRCLE  : menus[active]->OnCircle(controller); break;
    case FEMENUCMD_L1      : menus[active]->OnL1(controller); break;
    case FEMENUCMD_R1      : menus[active]->OnR1(controller); break;
    case FEMENUCMD_L2      : menus[active]->OnL2(controller); break;
    case FEMENUCMD_R2      : menus[active]->OnR2(controller); break;
    default: ;
    }
}
